#define CAPTURED_TEST_HELPERS_ONLY
#include "CapturedNVNProgramTest.c"
#include "GuestCapturedPrograms.h"
static SatchelGuestCapturedPrograms *observed;
static unsigned fail_forget;
uint32_t capture_test_call(SatchelGuestCapturedPrograms*o,SatchelCPUProbe*cpu,uint64_t p,int32_t n,uint64_t d,SatchelGuestCapturedProgramInfo*out){uint32_t s=satchel_guest_captured_programs_capture(o,cpu,p,n,d,out);if(!s)observed=o;return s;}
uint32_t forget_test_call(SatchelGuestCapturedPrograms*o,uint64_t p,uint64_t g){if(fail_forget){--fail_forget;return SATCHEL_GCAP_BUSY;}return satchel_guest_captured_programs_forget(o,p,g);}
int main(void){(void)capture_boundary;(void)legacy_regression;Interpreted f;makei(&f);CHECK(I(&f,"nvnProgramInitialize",IPROGRAM,IDEV,0,0,0,0)==1);captured_shader(&f,0,0);CHECK(I(&f,"nvnProgramSetShaders",IPROGRAM,2,ISHDATA,0,0,0)==1);CHECK(observed);uint64_t reference=0;SatchelGuestCapturedProgramInfo info;CHECK(satchel_guest_captured_programs_retain(observed,f.cpu,IPROGRAM,&reference,&info)==SATCHEL_GCAP_OK&&reference);calli(&f,"nvnProgramFinalize",IPROGRAM,0,0,0,0,0,SATCHEL_GUEST_DISPATCH_RESOURCE_BUSY);calli(&f,"nvnProgramSetShaders",IPROGRAM,2,ISHDATA,0,0,0,SATCHEL_GUEST_DISPATCH_RESOURCE_BUSY);CHECK(satchel_guest_captured_programs_release(observed,reference)==SATCHEL_GCAP_OK);fail_forget=1;calli(&f,"nvnProgramFinalize",IPROGRAM,0,0,0,0,0,SATCHEL_GUEST_DISPATCH_RESOURCE_BUSY);calli(&f,"nvnProgramSetShaders",IPROGRAM,2,ISHDATA,0,0,0,SATCHEL_GUEST_DISPATCH_RESOURCE_BUSY);V(&f,"nvnProgramFinalize",IPROGRAM,0,0,0,0,0);V(&f,"nvnMemoryPoolFinalize",IPOOL+256,0,0,0,0,0);dropi(&f);CHECK(!satchel_vulkan_device_live_count());printf("Captured actual reference and finalize-retry: %u assertions; test-only observer/failure wrapper.\n",checks);return 0;}
